/**
 * Add shared command options to command arguments.
 *
 * @param array $newArgs The command arguments to update.
 * @param \Cake\Console\Arguments $args The command arguments.
 * @return array
 */
protected function addCommonCommandOptions(array $newArgs, Arguments $args): array
{
    if ($args->getOption('connection')) {
        $newArgs[] = '-c';
        $newArgs[] = $args->getOption('connection');
    }

    if ($args->getOption('plugin')) {
        $newArgs[] = '-p';
        $newArgs[] = $args->getOption('plugin');
    }

    if ($args->getOption('source')) {
        $newArgs[] = '-s';
        $newArgs[] = $args->getOption('source');
    }

    return $newArgs;
}

